import {defaultPhotoFrame} from '../../src/utils/defaultPhotoFrame.js';import {loadFrameImage} from '../../src/utils/photoFrame.js';import React,{useState} from 'react';import{createRoot}from'react-dom/client';import PhotoFrame from '../../src/components/templates/shared/PhotoFrame.jsx';import{THEME_CATALOG}from'../../src/config/themeCatalog.js';
function App(){const[result,setResult]=useState('');return <main style={{background:'#f5f1e7',padding:24,color:'#526345',font:'14px Georgia',maxWidth:1040,margin:'auto'}}><button onClick={async()=>{try{for(const t of THEME_CATALOG){const img=await loadFrameImage(defaultPhotoFrame(t.id)),c=document.createElement('canvas');c.width=600;c.height=800;const ctx=c.getContext('2d');ctx.drawImage(img,0,0);const center=ctx.getImageData(300,400,1,1).data[3];if(center!==0)throw Error('Area tengah tidak transparan: '+t.name);const blob=await new Promise(r=>c.toBlob(r,'image/png'));if(!blob?.size)throw Error('Ekspor gagal: '+t.name)}setResult('6 bingkai: transparansi dan ekspor PNG berhasil')}catch(e){setResult(e.message)}}}>Uji ekspor PNG</button><p role="status">{result}</p><h1 style={{fontSize:26,fontWeight:400}}>Bingkai Foto — koleksi template aktif</h1><div style={{display:'grid',gridTemplateColumns:'repeat(3,1fr)',gap:24}}>{THEME_CATALOG.map(t=><article key={t.id} style={{textAlign:'center'}}><h2 style={{fontSize:20,fontWeight:400}}>{t.name}</h2><PhotoFrame themeId={t.id}/></article>)}</div></main>};createRoot(document.getElementById('root')).render(<App/>);
